//! The rulebook as one Markdown page (`docs/RULEBOOK.md`, written by `cargo
//! xtask rulebook`; the approved test `rulebook` fails when it is stale).

use std::fmt::Write as _;

use crate::{BOOK, EDITION, Entry, Kind, TABLE_CHANGES};

/// The whole book as Markdown.
pub fn markdown() -> String {
    let mut out = String::new();
    let _ = writeln!(out, "# The rulebook\n");
    let _ = writeln!(
        out,
        "<!-- @generated by `cargo xtask rulebook` from data/rules/*.toml; edit those, never this. -->\n"
    );
    let _ = writeln!(
        out,
        "Every number the game's own rules use, and what it does. The game reads \
         these very values: change one in `data/rules/`, build, and the game plays \
         by it. The numbers a game's data holds (a weapon's dice, a power's cost, a \
         feat's row) are the game install's own; `kjk rules` lists them as the \
         game reads them, beside these.\n"
    );
    let _ = writeln!(out, "Edition `{EDITION:016x}`.\n");
    let _ = writeln!(out, "## Contents\n");
    for entry in BOOK.iter().filter(|entry| entry.depth <= 1) {
        let indent = "  ".repeat(entry.depth);
        let _ = writeln!(out, "{indent}- [{}](#{})", entry.title, anchor(entry.path));
    }
    out.push('\n');
    for entry in BOOK {
        match entry.kind {
            Kind::Section => section(&mut out, entry),
            Kind::Rule { .. } => rule(&mut out, entry),
        }
    }
    changes(&mut out);
    out
}

/// The rulebook's changes to the games' own tables.
fn changes(out: &mut String) {
    let _ = writeln!(
        out,
        "## Changes to the games' tables
"
    );
    if TABLE_CHANGES.is_empty() {
        let _ = writeln!(
            out,
            "None: the game reads its tables as the install has them \
             (`data/rules/tables/<game>/<table>.toml` would change a cell).\n"
        );
        return;
    }
    let _ = writeln!(out, "| Game | Table | Row | Column | Now | Why |");
    let _ = writeln!(out, "|---|---|---|---|---|---|");
    for change in TABLE_CHANGES {
        let _ = writeln!(
            out,
            "| {} | `{}.2da` | {} | `{}` | {} | {} |",
            change.game,
            change.table,
            cell(change.row),
            change.column,
            cell(change.value),
            cell(change.why)
        );
    }
    out.push('\n');
}

/// A page anchor for an entry: its path, dots as dashes.
pub fn anchor(path: &str) -> String {
    path.replace(['.', '_'], "-")
}

fn section(out: &mut String, entry: &Entry) {
    let hashes = "#".repeat((entry.depth + 2).min(6));
    let _ = writeln!(
        out,
        "{hashes} <a id=\"{}\"></a>{}\n",
        anchor(entry.path),
        entry.title
    );
    paragraph(out, entry.summary);
    paragraph(out, entry.detail);
}

fn rule(out: &mut String, entry: &Entry) {
    let Kind::Rule {
        unit,
        labels,
        source,
        see,
        ..
    } = entry.kind
    else {
        return;
    };
    let _ = writeln!(
        out,
        "<a id=\"{}\"></a>**{}** = **{}**{} · `{}`\n",
        anchor(entry.path),
        entry.title,
        entry.value(),
        written(entry),
        entry.path
    );
    if !labels.is_empty() {
        let row: Vec<String> = labels
            .iter()
            .zip(entry.values)
            .map(|(label, value)| format!("{label} **{}**", crate::shown::said(value, unit)))
            .collect();
        let _ = writeln!(out, "{}\n", row.join(" · "));
    }
    paragraph(out, entry.summary);
    paragraph(out, entry.detail);
    let mut notes = Vec::new();
    if !source.is_empty() {
        notes.push(format!("Source: {source}."));
    }
    if !see.is_empty() {
        notes.push(format!("Code: `{see}`."));
    }
    if !notes.is_empty() {
        let _ = writeln!(out, "<sub>{}</sub>\n", notes.join(" "));
    }
}

fn paragraph(out: &mut String, text: &str) {
    if !text.is_empty() {
        let _ = writeln!(out, "{text}\n");
    }
}

/// A Markdown table cell's text: its pipes escaped.
fn cell(text: &str) -> String {
    text.replace('|', "\\|")
}

/// The value as the book writes it, after the said one where they differ:
/// ` (`3000 ms`)`.
fn written(entry: &Entry) -> String {
    let written = entry.written();
    if written == entry.value() {
        String::new()
    } else {
        format!(" (`{written}`)")
    }
}
